import math

# Function to calculate binomial coefficient
def binom(n, k):
    if k > n:
        return 0
    return math.comb(n, k)

# Calculate the number of valid ordered pairs
N = 0
for n in range(1, 13):
    if n != 6 and (12 - n) != 6:
        N += binom(12 - n, n)

print(N)
```
